# -*- coding: utf-8 -*-
import json, io

W = "https://en.wiktionary.org/wiki/"
data = {
 "pdf_page": 425,
 "book_page": 395,
 "verified_by": "claude-opus-5",
 "verified_on": "2026-09-13",
 "entries": [
  {
   "entry": 0,
   "root": "Reuto, Routo, Rut",
   "verdict": "confirmed",
   "modern_form": "PIE *reuto-, *routo-, *rut- 'stomach, intestines (of an animal)'",
   "note": "Pokorny's entry 'reuto-, routo- rut-, Meaning: stomach, intestines (of an animal)' runs over pp. 873-874, so Nourai's POK:873 for the root box and POK:874 for the nodes are both right. The root label 'Indo-European' is correct only in a weak sense: the root rests on an Iranian-Germanic isogloss (MP rot, NP ruda, Av. uruθwar-/-wan-; OE reada, Du. roode, Swed. dial. rudda), Pokorny's only authority being Liden, KZ 61, 14 f. It is absent from Walde-Pokorny (1927-32) and from Watkins/AHD, so it is a post-1932 addition rather than a classical IE root. The gloss Nourai gives ('intestines, bowels') matches Pokorny.",
   "note_fa": "ریشهٔ هندواروپایی آغازین *reuto-/*routo-/*rut- به معنای «شکم، روده (جانور)» در فرهنگ پوکورنی (ص ۸۷۳–۸۷۴) آمده است و ادعای نورایی درست است. باید دانست که این ریشه فقط بر پایهٔ همسانی زبان‌های ایرانی و ژرمنی بازسازی شده و پوکورنی تنها به لیدن (KZ 61) استناد کرده است؛ در والده–پوکورنی و در فهرست واتکینز (AHD) این ریشه نیست.",
   "sources": ["https://en.wiktionary.org/wiki/%D8%B1%D9%88%D8%AF%D9%87"],
   "ref_check": [
    {"ref": "POK:873", "status": "supports", "note": "POK_full.txt (indo-european.info dump), block 'Root / lemma: reuto-, routo- rut- / Meaning: stomach, intestines (of an animal) ... Page(s): 873-874'; material: 'Middle Persian rot ‘intestines, entrails of Rindes’, npers. ruda, Pl. rudag-an ... jav. uruθwara, -wan- n. (*rut-uar-, -uan-) ‘intestines, entrails, belly’; Old English reada ... References: Liden KZ. 61, 14 f.' (grep -n 'lemma: reuto' POK_full.txt -> line 70898)."}
   ],
   "consulted": [
    {"src": "POK", "where": "pp. 873-874 s.v. reuto-, routo- rut-", "stance": "supports", "note": "gloss and all four daughter branches (MP, NP, Av., Gmc.) as drawn by Nourai."},
    {"src": "WLD", "where": "Bd. II (1927)", "stance": "silent", "note": "Pokorny gives no 'WP.' cross-reference for this root (only 'Liden KZ. 61, 14 f.'), i.e. the root is not in Walde-Pokorny; grep of WLD_Bd2_pages.txt for 'reuto', 'routo', 'uruθwar' found nothing (OCR is also very poor)."},
    {"src": "AHD", "where": "Watkins 1985, IE roots R-", "stance": "silent", "note": "AHD_watkins1985.txt has reu-1, reu-2, reudh-1, reudh-2, reuə-, reug-, reugh-men-, reup-, rezg- but NO *reuto- 'intestines' — Watkins does not recognise the root."},
    {"src": "IEC", "where": "Mann s.v. reut-", "stance": "silent", "note": "IEC.txt line 14581 'reut- (reuto, ið, rout-, rut-) ‘fling, dash’. Cf. routeio' — Mann's reut- is a different root ('fling'); he has no 'intestine' root."}
   ],
   "nodes": [
    {
     "id": 1, "lang": "Avestan", "words": "uruthwara, uruthwan, uruthwasča",
     "verdict": "confirmed",
     "derivation": "Bartholomae's headword is 'j. uruθwan-, -θwar- n. ‘Eingeweide, Bauch’' (AiW col. 1530-33), an r/n-heteroclitic neuter of the archaic type *rut-uar- / *rut-uan- (Pokorny 874) built on the zero grade *rut- of *reuto-. Initial uru- is the regular Avestan prothetic/anaptyctic rendering of syllabic r (r̥ > ǝrǝu > uru-), and -θw- is *-tw- with the regular Avestan t > θ before w. The third form, uruθwąsca, is not a separate stem but the attested nom.-acc. plural uruθwą with the enclitic -ca 'and' (Yt 13.11 astica gaonaca ... uruθwąsca pasūsca), the -ąs- being the regular sandhi of -ą + ca; Nourai lists an inflected text-form beside two stems. The word is used of the entrails of 'Ahuric' (good) creatures, the daevic counterpart being maršu-. Meaning 'entrails, belly' is correct; V 4.48 yō gəuš uruθwarə ham.pafraιti and the figurative V 5.30 'the core (of the religion)' are Bartholomae's citations.",
     "derivation_fa": "در اوستا ستاک uruθwan-/uruθwar- (خنثی) به معنای «روده، اندرونه، شکم» است (بارتولومه، ستون ۱۵۳۰–۳۳) که از نوع نام‌های دوگانه‌ستاک r/n است: *rut-uar-/*rut-uan-. اولِ uru- همان بازتابِ معمولِ rِ هجایی هندواروپایی در اوستایی است و -θw- دگرگونی آوایی *-tw- است. صورت سوم (uruθwąsca) ستاک جداگانه‌ای نیست، بلکه جمع uruθwą به افزودنِ پیوستهٔ -ca «و» است (یشت ۱۳،۱۱). ادعای نورایی درست است.",
     "sources": ["https://starlingdb.org/new100/irn.pdf"],
     "ref_check": [
      {"ref": "POK:874", "status": "supports", "note": "POK_full.txt s.v. reuto-: 'jav. uruθwara, -wan- n. (*rut-uar-, -uan-) ‘intestines, entrails, belly’' — exactly the arrow drawn."}
     ],
     "consulted": [
      {"src": "BRT", "where": "col. 1530-33 s.v. uruθwan-, -θwar-", "stance": "supports", "note": "BRT.txt line 25521: '• j. uruθwan-, -θwar- n. ‘Eingeweide, Bauch’ ... auch Plur.: astica gaonaca ... uruθwąsca pasūsca fravāxšasca Yt 13.11'; and the closing note 'Vgl. np. rūda, nbal. rōδ ‘Eingeweide’; Bthl. IF. 5.228.' — Bartholomae himself links the Avestan word with NP rūda."},
      {"src": "POK", "where": "p. 874", "stance": "supports", "note": "as in ref_check."},
      {"src": "PHD", "where": "MacKenzie p. 84 s.v. *uruspar", "stance": "supports", "note": "PHD.txt line 599: '*uruspar [ʾwlwspl = Av. uruθβar-] intestines, womb; core, essence' — MacKenzie knows an actual Pahlavi continuation of the Avestan word, and its senses ('intestines, womb; core') match Bartholomae's."},
      {"src": "KNT", "where": "Old Persian lexicon", "stance": "silent", "note": "no Old Persian cognate of uruθwar- is recorded."}
     ]
    },
    {
     "id": 2, "lang": "Pahlavi", "words": "aškumb",
     "verdict": "disputed",
     "derivation": "Pahlavi aškamb / aškom(b) [ʾškmb, ʾskwm(b)] 'belly, womb' is real (MacKenzie p. 12; Nyberg II, s.v.), and it is indeed the word the Zand uses to render Avestan uruθwan-: Bartholomae notes at the end of the entry 'Pü. (ru F.): škamb', and Tavoosi's Šāyest-nē-Šāyest glossary (SNS p. 36) prints aškumb with the Avestan uruθwąsca beside it. But that is a TRANSLATION equivalence in the Pahlavi version, not a phonetic descent: uruθwan-/uruθwar- cannot yield aškamb by any Middle Persian sound law (there is no source for the šk- cluster or the -mb), and MacKenzie records the genuine Middle Persian continuant of Av. uruθβar- separately as *uruspar 'intestines, womb; core, essence'. aškamb is an independent Iranian word: cf. Manichaean MP škmb, Sogdian škmb, Pazand aškum/iškam, Yaghnobi šikampa/iškampá 'stomach', for which Morgenstierne-type reconstructions start from *(s)kamb-/*stamb-, not from *rut-. Nourai's arrow therefore mistakes a Zand gloss for an etymology.",
     "derivation_fa": "واژهٔ فارسی میانهٔ aškamb/aškomb «شکم، زهدان» درست است (مکنزی ص‌۱۲؛ نیبرگ)، و در زند، همین واژه برابرِ اوستاییِ uruθwan- آورده شده است (بارتولومه: «Pü. škamb»؛ واژه‌نامهٔ شایست نه شایست ص‌۳۶). اما این فقط برابرنهادِ ترجمه‌ای است و نه تحولِ آوایی؛ از uruθwar- به هیچ روی نمی‌توان aškamb ساخت، و مکنزی بازماندهٔ راستینِ آن را جداگانه *uruspar «روده، زهدان» ثبت کرده است. aškamb واژه‌ای جداست (قیاس کنید سغدی و مانوی škmb، پازند aškum، یغنابی šikampa). بنابراین پژوهش امروزی پیکانِ نورایی را رد می‌کند: این یک «برابرِ زندی» است، نه ریشهٔ آوایی.",
